-- Recipe images (PLAN.md 3.7 and 8.4): a cover per recipe and a photo gallery.
--
--   * Storage: private bucket `recipe-images`, objects at `<household_id>/<recipe_id>/<uuid>.<ext>`. Members read
--     and write only their household's folder (first path segment). JPEG/PNG/WebP up to 5 MB; the apps resize
--     to ~1600 px before uploading (image transformations are not on the free plan).
--   * recipes.image_path is the cover's object path; recipes.image_source says where it came from: 'photo'
--     (taken or picked in the app) or 'ai' (generated by an agent through the MCP). Agents never replace a photo
--     cover unless told to.
--   * recipe_photos: the gallery, a new synced table (sync contract: synced_tables, pull_changes, purge order,
--     push reason 'recipes', cascade tombstone with its recipe).

-- ---------------------------------------------------------------------------
-- Storage
-- ---------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('recipe-images', 'recipe-images', false, 5242880, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do update set
  public = excluded.public,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

create policy recipe_images_select on storage.objects for select to authenticated
  using (
    bucket_id = 'recipe-images'
    and (storage.foldername(name))[1] in (select h::text from public.household_ids_for_user() h)
  );
create policy recipe_images_insert on storage.objects for insert to authenticated
  with check (
    bucket_id = 'recipe-images'
    and (storage.foldername(name))[1] in (select h::text from public.household_ids_for_user() h)
  );
create policy recipe_images_update on storage.objects for update to authenticated
  using (
    bucket_id = 'recipe-images'
    and (storage.foldername(name))[1] in (select h::text from public.household_ids_for_user() h)
  )
  with check (
    bucket_id = 'recipe-images'
    and (storage.foldername(name))[1] in (select h::text from public.household_ids_for_user() h)
  );
create policy recipe_images_delete on storage.objects for delete to authenticated
  using (
    bucket_id = 'recipe-images'
    and (storage.foldername(name))[1] in (select h::text from public.household_ids_for_user() h)
  );

-- ---------------------------------------------------------------------------
-- Cover source
-- ---------------------------------------------------------------------------
alter table public.recipes add column image_source text;
alter table public.recipes
  add constraint recipes_image_source_check check (image_source in ('photo', 'ai'));

-- ---------------------------------------------------------------------------
-- recipe_photos (synced)
-- ---------------------------------------------------------------------------
create table public.recipe_photos (
  id uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households (id) on delete cascade,
  recipe_id uuid not null,
  storage_path text not null check (length(btrim(storage_path)) > 0),
  width integer check (width > 0),
  height integer check (height > 0),
  position integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid default auth.uid() references auth.users (id) on delete set null,
  deleted_at timestamptz,
  client_updated_at timestamptz,
  server_seq bigint not null default 0,
  unique (id, household_id),
  foreign key (recipe_id, household_id) references public.recipes (id, household_id) on delete cascade
);

create trigger t10_sync_row before insert or update on public.recipe_photos
  for each row execute function private.sync_row();
create index recipe_photos_household_id_idx on public.recipe_photos (household_id);
create index recipe_photos_server_seq_idx on public.recipe_photos (server_seq);
create index recipe_photos_deleted_at_idx on public.recipe_photos (deleted_at) where deleted_at is not null;
create index recipe_photos_recipe_id_idx on public.recipe_photos (recipe_id);

create trigger t90_enqueue_push after insert or update on public.recipe_photos
  for each row execute function private.enqueue_sync_push('recipes');
create trigger t35_tombstone_recipe_photos after update of deleted_at on public.recipes
  for each row execute function private.cascade_tombstone('recipe_photos', 'recipe_id');

alter table public.recipe_photos enable row level security;
create policy recipe_photos_select on public.recipe_photos for select to authenticated
  using (household_id in (select public.household_ids_for_user()));
create policy recipe_photos_insert on public.recipe_photos for insert to authenticated
  with check (household_id in (select public.household_ids_for_user()));
create policy recipe_photos_update on public.recipe_photos for update to authenticated
  using (household_id in (select public.household_ids_for_user()))
  with check (household_id in (select public.household_ids_for_user()));
revoke all on public.recipe_photos from anon;
revoke delete, truncate on public.recipe_photos from authenticated;
grant select, insert, update on public.recipe_photos to authenticated;

-- ---------------------------------------------------------------------------
-- Synced table list, pull and purge (recipe_photos after recipes)
-- ---------------------------------------------------------------------------
create or replace function public.synced_tables()
returns text[]
language sql
immutable
set search_path = ''
as $$
  select array[
    'stores', 'products', 'product_stores', 'recipes', 'recipe_ingredients', 'recipe_components', 'recipe_photos',
    'meal_plan_drafts', 'meal_plan_entries', 'consumptions', 'shopping_entries', 'shopping_entry_items',
    'frozen_items'
  ]::text[];
$$;

create or replace function public.pull_changes(p_cursor bigint default 0, p_limit integer default 500)
returns jsonb
language plpgsql
stable
security invoker
set search_path = ''
as $$
declare
  v_cursor bigint := greatest(coalesce(p_cursor, 0), 0);
  v_limit integer := greatest(1, least(coalesce(p_limit, 500), 1000));
  v_rows jsonb;
  v_count integer;
  v_has_more boolean;
  v_watermark bigint := public.sync_purge_watermark();
begin
  with changes as (
    select 'stores' as t, x.server_seq, to_jsonb(x) as r from public.stores x where x.server_seq > v_cursor
    union all
    select 'products', x.server_seq, to_jsonb(x) from public.products x where x.server_seq > v_cursor
    union all
    select 'product_stores', x.server_seq, to_jsonb(x) from public.product_stores x where x.server_seq > v_cursor
    union all
    select 'recipes', x.server_seq, to_jsonb(x) from public.recipes x where x.server_seq > v_cursor
    union all
    select 'recipe_ingredients', x.server_seq, to_jsonb(x) from public.recipe_ingredients x where x.server_seq > v_cursor
    union all
    select 'recipe_components', x.server_seq, to_jsonb(x) from public.recipe_components x where x.server_seq > v_cursor
    union all
    select 'recipe_photos', x.server_seq, to_jsonb(x) from public.recipe_photos x where x.server_seq > v_cursor
    union all
    select 'meal_plan_drafts', x.server_seq, to_jsonb(x) from public.meal_plan_drafts x where x.server_seq > v_cursor
    union all
    select 'meal_plan_entries', x.server_seq, to_jsonb(x) from public.meal_plan_entries x where x.server_seq > v_cursor
    union all
    select 'consumptions', x.server_seq, to_jsonb(x) from public.consumptions x where x.server_seq > v_cursor
    union all
    select 'shopping_entries', x.server_seq, to_jsonb(x) from public.shopping_entries x where x.server_seq > v_cursor
    union all
    select 'shopping_entry_items', x.server_seq, to_jsonb(x) from public.shopping_entry_items x where x.server_seq > v_cursor
    union all
    select 'frozen_items', x.server_seq, to_jsonb(x) from public.frozen_items x where x.server_seq > v_cursor
  ),
  page as (
    select * from changes order by server_seq limit v_limit + 1
  )
  select coalesce(jsonb_agg(jsonb_build_object('table', page.t, 'row', page.r) order by page.server_seq), '[]'::jsonb),
         count(*)
  into v_rows, v_count
  from page;

  v_has_more := v_count > v_limit;
  if v_has_more then
    v_rows := v_rows - v_limit;
  end if;

  return jsonb_build_object(
    'rows', v_rows,
    'has_more', v_has_more,
    'cursor', coalesce((v_rows -> -1 -> 'row' ->> 'server_seq')::bigint, v_cursor),
    'reset_required', v_cursor > 0 and v_cursor < v_watermark
  );
end;
$$;

create or replace function public.purge_tombstones(p_older_than interval default interval '30 days')
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_cutoff timestamptz := now() - p_older_than;
  v_table text;
  v_count bigint;
  v_max bigint;
  v_watermark bigint := 0;
  v_counts jsonb := '{}'::jsonb;
  v_queue bigint;
begin
  foreach v_table in array array[
    'frozen_items', 'shopping_entry_items', 'shopping_entries', 'consumptions', 'meal_plan_entries', 'meal_plan_drafts',
    'recipe_photos', 'recipe_components', 'recipe_ingredients', 'recipes', 'product_stores', 'products', 'stores'
  ] loop
    execute format(
      'with d as (delete from public.%I where deleted_at < $1 returning server_seq) select count(*), max(server_seq) from d',
      v_table
    ) into v_count, v_max using v_cutoff;
    v_counts := v_counts || jsonb_build_object(v_table, v_count);
    v_watermark := greatest(v_watermark, coalesce(v_max, 0));
  end loop;

  with d as (delete from public.push_queue where sent_at < now() - interval '7 days' returning 1)
  select count(*) into v_queue from d;

  update private.sync_state
  set purge_watermark = greatest(purge_watermark, v_watermark),
      last_purge_at = now(),
      keepalive_at = now()
  where id;

  return jsonb_build_object(
    'purged', v_counts,
    'push_queue_trimmed', v_queue,
    'watermark', public.sync_purge_watermark(),
    'at', now()
  );
end;
$$;

-- ---------------------------------------------------------------------------
-- MCP: recipe images
-- ---------------------------------------------------------------------------
-- Recipes without a cover, with what an agent needs to picture the dish.
create or replace function public.mcp_recipes_missing_cover(p_limit integer default 20)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
  select coalesce(jsonb_agg(row_to_json(x)::jsonb order by x.name), '[]'::jsonb)
  from (
    select r.id, r.name, r.meal_types, r.steps, r.notes,
      coalesce((
        select jsonb_agg(p.name order by i.position, p.name)
        from public.recipe_ingredients i
        join public.products p on p.id = i.product_id
        where i.recipe_id = r.id and i.deleted_at is null
      ), '[]'::jsonb) as ingredients
    from public.recipes r
    where r.deleted_at is null and r.image_path is null
    order by r.name
    limit greatest(1, least(coalesce(p_limit, 20), 200))
  ) x;
$$;

-- Validates that an uploaded object belongs to the recipe's folder and exists in storage.
create or replace function public.mcp_check_recipe_image(p_recipe_id uuid, p_path text)
returns void
language plpgsql
stable
security invoker
set search_path = ''
as $$
declare
  v_household uuid;
begin
  select r.household_id into v_household from public.recipes r where r.id = p_recipe_id and r.deleted_at is null;
  if v_household is null then
    raise exception 'recipe not found' using errcode = 'no_data_found';
  end if;
  if p_path is null or p_path not like v_household::text || '/' || p_recipe_id::text || '/%' then
    raise exception 'the image is not in this recipe''s folder' using errcode = 'invalid_parameter_value';
  end if;
  if not exists (select 1 from storage.objects o where o.bucket_id = 'recipe-images' and o.name = p_path) then
    raise exception 'the image has not been uploaded' using errcode = 'no_data_found';
  end if;
end;
$$;

-- Sets an agent-made cover. A cover that already exists (above all, a photo from the app) is kept unless
-- p_overwrite is true.
create or replace function public.mcp_set_recipe_cover(p_recipe_id uuid, p_path text, p_overwrite boolean default false)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_current text;
begin
  perform public.mcp_check_recipe_image(p_recipe_id, p_path);
  select r.image_path into v_current from public.recipes r where r.id = p_recipe_id;
  if v_current is not null and not coalesce(p_overwrite, false) then
    raise exception 'the recipe already has a cover; pass overwrite to replace it' using errcode = 'object_not_in_prerequisite_state';
  end if;
  update public.recipes set image_path = p_path, image_source = 'ai' where id = p_recipe_id;
  return jsonb_build_object('recipe_id', p_recipe_id, 'image_path', p_path, 'replaced', v_current is not null);
end;
$$;

create or replace function public.mcp_add_recipe_photo(
  p_recipe_id uuid,
  p_path text,
  p_width integer default null,
  p_height integer default null
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_household uuid;
  v_id uuid := gen_random_uuid();
  v_position integer;
begin
  perform public.mcp_check_recipe_image(p_recipe_id, p_path);
  select r.household_id into v_household from public.recipes r where r.id = p_recipe_id;
  select coalesce(max(p.position), -1) + 1 into v_position
  from public.recipe_photos p
  where p.recipe_id = p_recipe_id and p.deleted_at is null;
  insert into public.recipe_photos (id, household_id, recipe_id, storage_path, width, height, position)
  values (v_id, v_household, p_recipe_id, p_path, p_width, p_height, v_position);
  return jsonb_build_object('photo_id', v_id, 'recipe_id', p_recipe_id, 'image_path', p_path);
end;
$$;

do $$
declare
  f text;
begin
  foreach f in array array[
    'mcp_recipes_missing_cover(integer)', 'mcp_check_recipe_image(uuid, text)',
    'mcp_set_recipe_cover(uuid, text, boolean)', 'mcp_add_recipe_photo(uuid, text, integer, integer)'
  ] loop
    execute format('revoke execute on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end;
$$;
